import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('passes valid input with an unlisted extra property to the executor unchanged, exactly once', async () => {
    const registry = new ToolRegistry();
    const received: Record<string, unknown>[] = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => {
        received.push(input);
        return 'sunny';
      }
    );

    await registry.execute('get_weather', {location: 'Berlin', extra: 1});

    expect(received).toEqual([{location: 'Berlin', extra: 1}]);
  });

  it('validates a function-valued tool definition against the schema current at each call', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    let requiredField = 'city';
    registry.register(
      () => ({
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {[requiredField]: {type: 'string'}},
          required: [requiredField],
        },
      }),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const first = await registry.execute('get_weather', {city: 'Berlin'});
    requiredField = 'location';
    const second = await registry.execute('get_weather', {city: 'Berlin'});
    const third = await registry.execute('get_weather', {location: 'Berlin'});

    expect({
      executorCalls,
      firstResult: first.result,
      secondRejectsMissingLocation: second.result.includes('location') && /required/i.test(second.result),
      thirdResult: third.result,
    }).toEqual({
      executorCalls: 2,
      firstResult: 'sunny',
      secondRejectsMissingLocation: true,
      thirdResult: 'sunny',
    });
  });

  it('compiles a static tool schema once across repeated execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    const definition = {
      name: 'get_weather',
      description: 'Get weather for a location',
      get inputSchema() {
        schemaReads += 1;
        return {type: 'object', properties: {location: {type: 'string'}}, required: ['location']};
      },
    };
    registry.register(definition, async () => 'sunny');
    const readsAtRegister = schemaReads;

    for (let call = 0; call < 10; call += 1) {
      await registry.execute('get_weather', {location: 'Berlin'});
    }

    expect(schemaReads).toBe(readsAtRegister);
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults ([validated by: passes valid input with an unlisted extra property to the executor unchanged, exactly once](../../src/orchestration/tools/registry.test.ts#L4)).
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema` ([validated by: compiles a static tool schema once across repeated execute calls](../../src/orchestration/tools/registry.test.ts#L66)).
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([validated by: validates a function-valued tool definition against the schema current at each call](../../src/orchestration/tools/registry.test.ts#L28)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).

